def remove_Occ(str, chr):
    n = len(str)
    #if there is only 1 character in the string and we need to remove first and last occurences of it
    if n == 1 and chr == str:
        return ""
    count = 0
    for i in str:
        if i == chr:
            count += 1
            if count == 1:
                #if we are removing the first occurence, we need to break out of the loop
                break
            #if we are removing the last occurence, we need to continue the loop
            else:
                continue
    #if we are removing the first occurence of the character, we need to add it to the string
    if count == 1:
        return str.replace(chr,"",1)
    #if we are removing the last occurence of the character, we need to add it to the string
    else:
        return str.replace(chr,"",1)
    
