import numpy as np
def sort_matrix(matrix):
  n = len(matrix)
  for i in range(n):
    for j in range(n):
      matrix[i][j] += n*(n+1)//2 - (i*(i+1)//2 + j)
  return np.sort(matrix, axis=0)

