def newman_conway(n):
    if n < 2:
        return "Invalid input: n must be a positive integer greater than or equal to 2"
    elif n == 2:
        return "1,1"
    elif n == 3:
        return "1,2,1"
    else:
        arr = [0]*(n+1)
        arr[1] = arr[2] = 1
        for i in range(3,n+1):
            arr[i] = arr[arr[i-1]] + arr[i-arr[i-1]]
        return "".join(str(x) for x in arr[2:n+1])

