def find_longest_repeating_subseq(str1):
    n = len(str1)
    # table to store the length of longest repeating subsequence
    table = [[0 for i in range(n)] for i in range(n)]

    # if the strings are same, the length is n
    for i in range(n):
        table[i][i] = 1

    # pick all substrings one by one
    for cl in range(2, n+1):  
        for i in range(n-cl+1):  
            j = i + cl-1

            # if the characters match at i and j,
            # then increment the count
            if str1[i] == str1[j] and i != j:
                table[i][j] = table[i+1][j-1] + 2

            # if the characters do not match
            # then update with maximum of the two.
            else:
                table[i][j] = max(table[i][j-1], table[i+1][j])

    # return the length of the longest repeating subsequence
    return table[0][n-1]
