def find_longest_repeating_subseq(s):
    n = len(s)
    # Create a 2D array of zeros to store lengths of longest repeating subsequences
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            # Base case: if strings are empty, length is 0
            if not s[i - 1] or not s[j - 1]:
                dp[i][j] = 0
            # If string characters at same index are same, add 1 to count of previous substrings
            elif s[i - 1] == s[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            # If characters at same index are different, take max of subproblems
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The answer is the last cell in the array
    return dp[n][n]
