def heap_replace(nums,element):
    nums.append(element)
    if nums == [] or len(nums) == 1:
        return nums
    i = len(nums)-1
    parent_index = i // 2
    while i > 0:
        if nums[i] > nums[parent_index]:
            nums[i], nums[parent_index] = nums[parent_index], nums[i]
            i = parent_index
            parent_index = i // 2
        else:
            break
    while i != 0:
        if nums[i] > nums[parent_index]:
            nums[i], nums[parent_index] = nums[parent_index], nums[i]
            i = parent_index
            parent_index = i // 2
        else:
            break
    nums.remove(element)
    return nums

def heap_replace( heap, replacement ):
  hq.heapreplace(heap, replacement)
  return heap

