def get_total_number_of_sequences(m, n):
    # Base case: if n == 1, only one possible sequence
    if n == 1:
        return m
    # Use dynamic programming to calculate the number of sequences
    # dp[i][j] represents the number of sequences with length i and the last element equal to j
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    # Initialize dp[1][j] to 1 for all j from 0 to m
    for j in range(m + 1):
        dp[1][j] = 1
    for i in range(2, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
    # Sum up all the sequences with length n
    total_sequences = sum(dp[n])
    return total_sequences

