def bi_sum(arr, n):
  prev = [0] * n
  cur = [0] * n
  for i in range(n):
    cur[i] = arr[i]
    if i > 0:
      prev[i] = max(prev[i-1], cur[i-1])
    else:
      prev[i] = 0
    cur[i] += prev[i]
  biSum = 0
  for i in range(n):
    j = n - i - 1
    biSum += max(prev[j], cur[j])
  return biSum

