def shell_sort(arr):
  gap = len(arr)//2

  while gap > 0:
    for i in range(gap, len(arr)):
      temp = arr[i]
      j = i
      while j >= gap and arr[j-gap] > temp:
        arr[j] = arr[j-gap]
        j -= gap
      arr[j] = temp
    gap //= 2

  return arr

def shell_sort(array):
    sub_arr = list(array)
    while True:
        sublist_count = len(sub_arr) // 2
        while sublist_count > 0:
            sublist_count = sublist_count // 2
            for start in range(sublist_count):
                merge_sort_sublists(sub_arr, start, sublist_count)
            if sublist_count == 1:
                break
        if sublist_count == 1:
            break
        sub_arr = list(array)
    return sub_arr
def merge_sort_sublists(sub_arr, start, sublist_count):
    i = start
    while i + sublist_count < len(sub_arr):
        mid = i + sublist_count
        end = min((i + 2 * sublist_count - 1), (len(sub_arr) - 1))
        merge_sublists(sub_arr, i, mid, end)
        i += 2 * sublist_count
def merge_sublists(arr, start, mid, end):
    sub_arr = arr[start:mid+1]
    while start <= mid and (mid+1 <= end):
        if arr[mid+1] > arr[start]:
            temp = arr[start]
            arr[start] = arr[mid+1]
            arr[mid+1] = temp
            mid += 1
        else:
            mid += 1
        start += 1
    temp_arr = sub_arr[start:]
    i = start
    while temp_arr:
        if temp_arr[i] > arr[mid]:
            arr[mid] = temp_arr[i]
            mid += 1
            temp_arr[i] = None
            i += 1
        else:
            temp_arr.pop(i)
            mid += 1
    arr[start:start+(end - start+1)] = temp_arr[:]

