def shell_sort(arr):
    # Function to find the value of next step in the shell sort algorithm
    def shell_step(size):
        return size // 2

    # Initialize the size
    size = len(arr)
    # Start from the largest step and reduce until the step is 0
    while shell_step(size) > 0:
        for step in range(shell_step(size), 0, -shell_step(size)):
            gap_insertion_sort(arr, step)
        size = shell_step(size)

    return arr


def gap_insertion_sort(arr, gap):
    for i in range(gap, len(arr)):
        j = i
        while j >= gap and arr[j - gap] > arr[j]:
            arr[j - gap], arr[j] = arr[j], arr[j - gap]
            j -= gap
    return arr

