  if l_nums:
    max_neg = sys.minint
    for num in l_nums:
      if num < 0 and num > max_neg:
        max_neg = num
    return max_neg
  else:
    return None

import heapq as hq
def largest_neg(num_list):
    neg_list = []
    for num in num_list:
        if num < 0:
            neg_list.append(num)

    if neg_list:
        largest_neg_num = hq.nlargest(1, neg_list)
        return largest_neg_num[0]
    else:
        return None

def largest_neg(nums):
  min_heap = []
  for num in nums:
      if num < 0:
          hq.heappush(min_heap, num)
  return min_heap[0]

