import copy
def trim_tuple(nums, k):
  new_nums = []
  for item in nums:
    new_nums.append(copy.deepcopy(item[1:-(k+1)]))  
  return new_nums

def trim_tuple(nums, k):
  trimmed_nums = []
  for num in nums:
      trimmed_num = tuple([x for x in num if x > k])
      trimmed_nums.append(trimmed_num)
  return trimmed_nums

def trim_tuple(nums, k):
  for i in nums:
    if len(i) > 1:
      i = tuple(i[k:])
    else:
      i = (i,)
    nums = nums.replace(str(i), str(''))
  return nums

def trim_tuple(test_tuple_list, k):
    res = tuple()
    for sub_tuple in test_tuple_list:
        trimmed_tuple = tuple(sub_tuple[:k])
        res = res + (trimmed_tuple,)
    return res

def trim_tuple(tuple_list,k):
  res = []
  for t in tuple_list:
    new_tuple = tuple(t[k: k+1])
    res.append(new_tuple)
  return str(res)

