def check_Triangle(a,b,c,d,e,f):
    x = (a,b) 
    y = (c,d) 
    z = (e,f)
    p = x[0]*y[1] + y[0]*z[1] + z[0]*x[1]
    q = x[0]*y[0] + y[0]*z[0] + z[0]*x[0]
    r = abs(x[1]-y[1])
    s = abs(y[1]-z[1])
    t = abs(z[1]-x[1])
    P = (r+s+t)
    if p*q >= P and p*r >= P:
      if (p*q == P) or (p*r == P) or (q*r == P):
        return 'Yes'
      elif p*q <= P and p*r <= P and q*r <= P:
        return 'Yes'
      else:
        return 'No'
    else:
      return 'No'

